package com.luci.pianoroom;
import java.io.*;
public final class LibraryPedalTest {
 static void check(boolean b,String s){SfzCompatibilityTest.check(b,s);}
 public static void main(String[] args)throws Exception{LibraryPedalSettings p=new LibraryPedalSettings();check(!p.pedalCustom&&!p.keyCustom,"neutral defaults");p.pedalCustom=true;p.pedalMs=1200;p.keyCustom=true;p.keyMs=250;LibraryPedalSettings q=LibraryPedalSettings.decode(p.encode());check(q.pedalCustom&&q.pedalMs==1200&&q.keyCustom&&q.keyMs==250,"persisted round trip");check(!LibraryPedalSettings.key(new File("A.prb")).equals(LibraryPedalSettings.key(new File("B.prb"))),"library isolation");for(String bad:new String[]{"1,NaN,0,500","1,9000,0,500","1,500,-1,500","1,500,0,0"})check(!LibraryPedalSettings.decode(bad).pedalCustom,"invalid stored policy falls back");File root=new File(args[0]).getParentFile();SfzCompatibilityTest.compile(root,"<region> sample=note.wav key=60 loop_mode=loop_continuous loop_start=0 loop_end=8191","legacy-pedal.prb");long h=Synth.load(args[0]);check(h!=0,"actual JNI bank");Synth.bankRelease(h,1200,250);long copy=Synth.copy(h,32);check(copy!=0,"policy survives copy");Synth.freeBank(h);Synth.bankRelease(copy,0,0);Synth.freeBank(copy);System.out.println("PASS: library pedal policy neutral defaults, persistent encoding, separate bank identities, invalid settings, actual JNI configuration/copy/reset.");}
}
